module hopscotch_counter(\n    input [7:0] N,\n    input [7:0] X,\n    input [7:0] Y,\n    output reg [31:0] result\n);\n\nlocalparam [31:0] MOD = 1000000007;\n\nfunction [31:0] inv;\n    input [7:0] i;\n    begin\n        case (i)\n            1: inv = 32'd1;\n            2: inv = 32'd500000004;\n            3: inv = 32'd333333336;\n            4: inv = 32'd250000002;\n            5: inv = 32'd400000003;\n            6: inv = 32'd166666668;\n            7: inv = 32'd142857144;\n            8: inv = 32'd125000001;\n            9: inv = 32'd111111112;\n            10: inv = 32'd100000001;\n            11: inv = 32'd90909091;\n            12: inv = 32'd83333334;\n            13: inv = 32'd76923077;\n            14: inv = 32'd71428572;\n            15: inv = 32'd66666667;\n            16: inv = 32'd62500001;\n            17: inv = 32'd58823530;\n            18: inv = 32'd55555556;\n            19: inv = 32'd52631579;\n            20: inv = 32'd50000001;\n            21: inv = 32'd47619048;\n            22: inv = 32'd45454546;\n            23: inv = 32'd43478261;\n            24: inv = 32'd41666667;\n            25: inv = 32'd40000001;\n            26: inv = 32'd38461539;\n            27: inv = 32'd37037037;\n            28: inv = 32'd35714286;\n            29: inv = 32'd34482759;\n            30: inv = 32'd33333334;\n            31: inv = 32'd32258065;\n            32: inv = 32'd31250001;\n            33: inv = 32'd30303031;\n            34: inv = 32'd29411765;\n            35: inv = 32'd28571429;\n            36: inv = 32'd27777778;\n            37: inv = 32'd27027027;\n            38: inv = 32'd26315790;\n            39: inv = 32'd25641026;\n            40: inv = 32'd25000001;\n            41: inv = 32'd24390244;\n            42: inv = 32'd23809524;\n            43: inv = 32'd23255814;\n            44: inv = 32'd22727273;\n            45: inv = 32'd22222222;\n            46: inv = 32'd21739131;\n            47: inv = 32'd21276596;\n            48: inv = 32'd20833334;\n            49: inv = 32'd20408164;\n            50: inv = 32'd20000001;\n            51: inv = 32'd19607844;\n            52: inv = 32'd19230770;\n            53: inv = 32'd18867925;\n            54: inv = 32'd18518519;\n            55: inv = 32'd18181819;\n            56: inv = 32'd17857143;\n            57: inv = 32'd17543860;\n            58: inv = 32'd17241380;\n            59: inv = 32'd16949153;\n            60: inv = 32'd16666667;\n            61: inv = 32'd16393443;\n            62: inv = 32'd16129033;\n            63: inv = 32'd15873016;\n            64: inv = 32'd15625001;\n            default: inv = 32'd0;\n        endcase\n    end\nendfunction\n\nfunction [31:0] mod_mul;\n    input [31:0] a;\n    input [31:0] b;\n    begin\n        mod_mul = (a * b) % MOD;\n    end\nendfunction\n\nfunction [31:0] binom;\n    input [7:0] n;\n    input [7:0] r;\n    integer i;\n    reg [31:0] prod;\n    begin\n        if (r > n)\n            binom = 32'd0;\n        else if (r == 8'd0)\n            binom = 32'd1;\n        else begin\n            prod = 32'd1;\n            for (i = 0; i < r; i = i + 1) begin\n                prod = mod_mul(prod, n - i);\n                prod = mod_mul(prod, inv(i+1));\n            end\n            binom = prod;\n        end\n    end\nendfunction\n\nalways @(*) begin\n    integer k;\n    reg [7:0] k_max;\n    reg [31:0] sum;\n    reg [31:0] binom1, binom2;\n    reg [7:0] n1, r1, n2, r2;\n    \n    k_max = 8'd0;\n    for (k = 1; k <= 64; k = k + 1) begin\n        if ((k * X) <= N && (k * Y) <= N) begin\n            k_max = k;\n        end\n    end\n    \n    sum = 32'd0;\n    for (k = 1; k <= 64; k = k + 1) begin\n        if (k <= k_max) begin\n            n1 = N - (k * X) + k - 8'd1;\n            r1 = k - 8'd1;\n            n2 = N - (k * Y) + k - 8'd1;\n            r2 = k - 8'd1;\n            binom1 = binom(n1, r1);\n            binom2 = binom(n2, r2);\n            sum = (sum + mod_mul(binom1, binom2)) % MOD;\n        end\n    end\n    \n    result = sum;\nend\n\nendmodule